ую гранату (Штурм)","no_accent":false,"enabled":true,"id":63,"category":"Спецсредства","wheel_car_group":"auto","wheel_car_extra_groups":[],"author_ref":"A63"},{"command_alias":"","wheel_group":"documents","parameters":{},"shortcut":{"alt":false,"ctrl":false,"shift":false,"key":0},"quick":false,"target_required":false,"script":"/me {gender:перехватил|перехватила} двуручный стальной таран обеими руками, {gender:размахнулся|размахнулась} и {gender:нанёс|нанесла} мощный удар в область дверного замка.\n@wait(1500)\n/do Замок вырван из дверной коробки, входная дверь распахнута внутрь помещения.","wheel_car_visible":false,"wheel_visible":true,"stat":"none","favorite":false,"command":"","skip_confirmation":true,"name":"Выбить дверь помещения штурмовым тараном","no_accent":false,"enabled":true,"id":64,"category":"Спецсредства","wheel_car_group":"auto","wheel_car_extra_groups":[],"author_ref":"A64"},{"command_alias":"","wheel_group":"documents","parameters":{},"shortcut":{"alt":false,"ctrl":false,"shift":false,"key":0},"quick":false,"target_required":false,"script":"/me {gender:расстегнул|расстегнула} подсумок индивидуальной аптечки IFAK, {gender:достал|достала} кровоостанавливающий турникет CAT и стерильный перевязочный пакет.\n@wait(1500)\n/me {gender:наложил|наложила} турникет выше места кровотечения, {gender:затянул|затянула} вороток до остановки крови и {gender:зафиксировал|зафиксировала} плотную давящую повязку.\n@wait(1500)\n/do Кровотечение у пострадавшего остановлено, состояние стабилизировано до прибытия парамедиков.","wheel_car_visible":false,"wheel_visible":true,"stat":"none","favorite":false,"command":"","skip_confirmation":false,"name":"Оказать Первую Медицинскую Помощь (ПМП / Жгут)","no_accent":false,"enabled":true,"id":65,"category":"Спецсредства","wheel_car_group":"auto","wheel_car_extra_groups":[],"author_ref":"A65"},{"command_alias":"","wheel_group":"documents","parameters":{},"shortcut":{"alt":false,"ctrl":false,"shift":false,"key":0},"quick":false,"targe